pub fn ct_allocator_is_installed_only_by_demand_test() -> String {
    v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat("    // THE COUNTING ALLOCATOR IS INSTALLED BY DEMAND AND BY NOTHING ELSE. Rendering the native claim\n".to_string(), "    // driver main for three binding sets: none (the pure main), a bound resource that is not the\n".to_string()), "    // AllocationCounter (the effect main), and the AllocationCounter binding. Only the last may carry a\n".to_string()), "    // #[global_allocator]; the first two are the negative controls, so a main that always rendered it\n".to_string()), "    // (or one that rendered it for any effect main) turns this row red.\n".to_string()), "    #[test]\n".to_string()), "    fn the_counting_allocator_is_installed_only_by_demand() {\n".to_string()), "        use crate::v1_compiler_emit_rust::emit_native_claim_driver_main_rs;\n".to_string()), "        let render = |bindings: Vec<std::rc::Rc<crate::v1_compiler_emit_rust::NativeEffectBindingText>>| -> String {\n".to_string()), "            emit_native_claim_driver_main_rs(\"c\".to_string(), \"m\".to_string(), std::rc::Rc::new(bindings.into())).content.clone()\n".to_string()), "        };\n".to_string()), "        let other = std::rc::Rc::new(crate::v1_compiler_emit_rust::NativeEffectBindingText {\n".to_string()), "            var: \"fs\".to_string(),\n".to_string()), "            type_path: \"c::std_filesystem::Filesystem\".to_string(),\n".to_string()), "            binding_line: \"    let fs = 0;\\n\".to_string(),\n".to_string()), "            argument: \"fs\".to_string(),\n".to_string()), "        });\n".to_string()), "        let counter = std::rc::Rc::new(crate::v1_compiler_emit_rust::NativeEffectBindingText {\n".to_string()), "            var: \"counter\".to_string(),\n".to_string()), "            type_path: \"c::std_realization_measurement::AllocationCounter\".to_string(),\n".to_string()), "            binding_line: \"    let counter = 0;\\n\".to_string(),\n".to_string()), "            argument: \"counter\".to_string(),\n".to_string()), "        });\n".to_string()), "        assert!(!render(Vec::new()).contains(\"#[global_allocator]\"), \"a pure main must carry no allocator\");\n".to_string()), "        assert!(!render(vec![other.clone()]).contains(\"#[global_allocator]\"), \"an effect main without the AllocationCounter must carry no allocator\");\n".to_string()), "        let registered = |main: &str| main.contains(\"register_counting_allocator(&COUNTING_ALLOCATOR)\");\n".to_string()), "        assert!(!registered(&render(Vec::new())), \"a pure main must register no provider\");\n".to_string()), "        assert!(!registered(&render(vec![other.clone()])), \"an effect main without the AllocationCounter must register no provider\");\n".to_string()), "        let demanding = render(vec![other, counter]);\n".to_string()), "        assert!(demanding.contains(\"#[global_allocator]\"), \"positive control: a main binding the AllocationCounter carries it\");\n".to_string()), "        assert!(registered(&demanding), \"the allocator and its registration come from the one selection\");\n".to_string()), "        assert!(demanding.find(\"register_counting_allocator\").unwrap() < demanding.find(\"native_claim_report(\").unwrap(), \"registration precedes the first read\");\n".to_string()), "    }\n\n".to_string())
}

